root=pathlib.Path("tools/core20k_sense_v1/release/v21-missing-batch500-all")
batchroot=pathlib.Path("tools/core20k_sense_v1/release/v21-missing-batch500-all")
entries=json.loads(r'''{"belle":["艳压群芳的美女","The novel describes a young ___ admired throughout the town.","美女"],"approvingly":["赞许地","The teacher nodded ___ at her answer.","赞许"],"beseech":["恳求","They ___ the council to reconsider its decision.","恳求"],"summarily":["迅速且不经充分程序地","The official was ___ dismissed after the investigation.","立即处理"],"cafe":["咖啡馆","They met at a small ___ near the station.","咖啡馆"],"republicanism":["共和主义","The historian traced the development of ___ in Europe.","共和主义"],"penthouse":["顶层豪华公寓","They rented a ___ overlooking the harbor.","顶层公寓"],"blandly":["平淡地；不动声色地","He ___ denied knowing anything about the incident.","平淡地"],"precautionary":["预防性的","The school announced ___ measures before the storm.","预防性"],"sate":["使充分满足","The enormous meal failed to ___ his appetite.","满足"],"gable":["山墙","A triangular ___ rose above the entrance.","山墙"],"seashore":["海岸","The children collected shells along the ___.","海岸"],"stupendous":["惊人的；巨大的","The bridge was a ___ engineering achievement.","惊人的"],"bluish":["带蓝色的","The mineral had a ___ tint.","带蓝色"],"heretofore":["迄今为止（正式）","The company revealed a ___ unknown problem.","迄今"],"tersely":["简短地","She replied ___ to the criticism.","简短地"],"archery":["射箭运动","He took lessons in ___ at the sports center.","射箭"],"windowsill":["窗台","A flowerpot stood on the ___.","窗台"],"chalice":["圣杯；高脚杯","The priest lifted the ceremonial ___.","圣杯"],"unexplored":["尚未探索的","The scientists entered an ___ cave.","未探索"],"piazza":["广场","Tourists gathered in the central ___.","广场"],"duchess":["公爵夫人；女公爵","The ___ welcomed guests to the palace.","女公爵"],"brusque":["简短生硬的","His ___ answer surprised the interviewer.","生硬"],"manorial":["庄园的","The village preserved an old ___ house.","庄园的"],"grandly":["盛大地；气派地","The hall was ___ decorated for the ceremony.","气派"],"compromiser":["愿意妥协的人","The mediator was known as a skilled ___.","妥协者"],"gerund":["动名词","The word swimming functions as a ___ in this sentence.","动名词"],"tripartite":["三方的","The three countries signed a ___ agreement.","三方"],"streetlight":["路灯","A broken ___ left the corner dark.","路灯"],"unaltered":["未经改动的","The manuscript remained ___ for decades.","未改动"],"teatime":["下午茶时间","They served cakes at ___.","下午茶"],"nefarious":["邪恶的；罪恶的","The investigators uncovered a ___ scheme.","邪恶"],"drudgery":["单调繁重的苦差事","Automation reduced the ___ of repetitive paperwork.","苦差"],"techie":["技术迷；技术专家（口语）","A local ___ helped repair the server.","技术迷"],"huntsman":["猎人","The ___ followed the animal's tracks.","猎人"],"oxidative":["氧化的","The study examined ___ damage to cells.","氧化的"],"playmate":["玩伴","Her childhood ___ lived next door.","玩伴"],"walrus":["海象","A ___ rested on the Arctic ice.","海象"],"deterministic":["确定性的","The simulator uses a ___ algorithm.","确定性"],"pedantic":["卖弄学问的；迂腐的","The critic found his explanation unnecessarily ___.","迂腐"],"termite":["白蚁","A ___ damaged the wooden beam.","白蚁"],"petticoat":["衬裙","The costume included a lace ___.","衬裙"],"rhythmically":["有节奏地","The dancers moved ___ to the drums.","有节奏"],"ember":["余烬","A glowing ___ remained in the fireplace.","余烬"],"southerner":["南方人（美国）","As a lifelong ___, she knew the region well.","美国南方人"],"mercilessly":["毫不留情地","The reviewer ___ criticized the film.","毫不留情"],"outpace":["超过；快于","Demand began to ___ supply.","超过"],"earthwork":["土垒；土方防御工事","The soldiers built an ___ around the camp.","土垒"],"pithy":["简练有力的","The editor preferred a ___ conclusion.","简练有力"],"energetically":["精力充沛地","She worked ___ throughout the afternoon.","精力充沛"],"starry":["布满星星的","They watched the ___ night sky.","繁星"],"casement":["平开窗","She opened the wooden ___ to let in air.","平开窗"],"profusely":["大量地；非常多地","He apologized ___ for the mistake.","反复地"],"injuriously":["有害地","The chemical reacted ___ with the surrounding material.","有害地"],"paddock":["赛马准备区","The horses waited in the ___ before the race.","赛马区"],"opulent":["豪华的","The guests entered an ___ dining room.","豪华"],"policyholder":["保单持有人","The insurer contacted each ___ about the changes.","投保人"],"plaintive":["哀伤的","A ___ cry came from the abandoned building.","哀伤"],"silverware":["银器；餐具","The restaurant polished its ___ before dinner.","银制餐具"],"brusquely":["生硬地","The manager ___ ended the conversation.","生硬"],"sociolinguistic":["社会语言学的","The paper examined ___ differences across communities.","社会语言学"],"instantaneously":["瞬间地","The message arrived almost ___.","瞬间"],"liaise":["联络协调","A coordinator will ___ with the partner organizations.","协调"],"innkeeper":["旅店老板","The ___ offered the travelers a warm meal.","旅店老板"],"humidify":["加湿","The device helps ___ the indoor air.","加湿"],"assiduous":["勤勉的","Her ___ research uncovered the missing documents.","勤勉"],"paucity":["匮乏；不足","The report noted a ___ of reliable data.","缺乏"],"auspicious":["吉利的；预示成功的","The clear weather was seen as an ___ sign.","吉利"],"amicably":["友好地","The parties resolved their dispute ___.","友好"],"pagoda":["宝塔","An ancient ___ stood above the village.","宝塔"],"barbarism":["野蛮行径","The historian condemned the act as ___.","野蛮行径"],"pulsar":["脉冲星","The telescope detected signals from a distant ___.","脉冲星"],"cordially":["热情友好地","The host greeted the visitors ___.","热情地"],"feudalism":["封建制度","The course examined ___ in medieval Europe.","封建制度"],"undemocratic":["不民主的","Opponents criticized the ___ procedure.","不民主"],"ceaseless":["不停歇的","The machinery made a ___ humming sound.","不停歇"],"feverishly":["狂热地；急切地","The engineers worked ___ to restore service.","急切"],"peruse":["仔细阅读","She paused to ___ the contract before signing.","仔细阅读"],"philology":["语文学；文献语言学","He studied classical ___ at university.","语文学"],"dynastic":["王朝的","The exhibition explored ___ politics in ancient China.","王朝"],"foreword":["前言","The author invited a colleague to write the ___.","前言"],"perilously":["危险地","The climber stood ___ close to the edge.","危险"],"ingratiate":["讨好；巴结","He tried to ___ himself with the new director.","讨好"],"omnipresent":["无处不在的","Mobile devices have become almost ___.","无处不在"],"tundra":["苔原","The researchers crossed the frozen ___.","苔原"],"nudity":["裸体状态","The exhibition included artwork depicting ___.","裸体状态"],"creditworthiness":["信用可靠程度","The bank assessed the applicant's ___.","信用水平"],"contemptuously":["轻蔑地","He ___ dismissed the proposal.","轻蔑"],"unjustly":["不公正地","She believed she had been ___ dismissed.","不公正"],"fondant":["翻糖；糖膏","The baker covered the cake with ___.","糖膏"],"dockyard":["造船厂；船舶维修厂","The vessel was repaired at the ___.","船厂"],"racquet":["球拍","She replaced the strings on her tennis ___.","球拍"],"mettle":["勇气；毅力","The crisis tested the team's ___.","勇气"],"acrimonious":["激烈争吵的；尖刻的","The meeting ended in an ___ dispute.","尖刻"],"rectory":["牧师住宅","The church renovated its old ___.","牧师住宅"],"bedstead":["床架","The carpenter restored a wooden ___.","床架"],"emotionality":["情绪性","The study explored the ___ of the responses.","情绪性"],"pedagogical":["教学法的","The teachers discussed ___ approaches.","教学法"],"captaincy":["队长职务","She accepted the ___ of the national team.","队长职务"],"uncontrollably":["无法控制地","He began shaking ___ in the cold.","无法控制"],"granary":["粮仓","The farmers stored wheat in the ___.","粮仓"],"expeditionary":["远征的","The military deployed an ___ force overseas.","远征"],"satirist":["讽刺作家","The ___ mocked corruption in his plays.","讽刺作家"],"unattainable":["无法达到的","The target seemed ___ without more funding.","无法达到"],"duomo":["主教座堂（意大利语）","They visited the historic ___ in Florence.","主教座堂"]}''')
allowed={r["lemma"]:r for line in (root/"next500_uncovered_source_cards.jsonl").open(encoding="utf8") for r in [json.loads(line)]}
assert set(entries).issubset(set(allowed)), "Attempted authoring of a word outside CURRENT deduplicated next500 source"
index=json.loads((batchroot/"index.json").read_text())
by_lemma={}
for b in index["batches"]:
    f=batchroot/("batch%03d"%b["batch"])/"bilingual_ku_editorial_candidates.jsonl"
    for line in f.open(encoding="utf8"):
        r=json.loads(line)
        if r["lemma"] in entries and r["editing_state"]=="EDITORIAL_SINGLE_GLOSS_CANDIDATE":
            by_lemma.setdefault(r["lemma"],[]).append(r)
with gzip.open("data/core20k-runtime.json.gz","rt",encoding="utf8") as f:
    words=json.load(f)["headwords"]
out=[];skipped={}
for lemma,(zh,prompt,cue) in entries.items():
    candidates=by_lemma.get(lemma,[])
    if len(candidates)!=1:
        skipped[lemma]="NOT_EXACTLY_ONE_LOW_RISK_SOURCE";continue
    r=candidates[0];rank=r["rank"]
    assert allowed[lemma]["rank"]==rank and allowed[lemma]["oewn_sense_id"]==r["oewn_sense_id"]
    assert words[rank-1][1].casefold()==lemma and prompt.count("___")==1
    response=lemma.title() if lemma in {"october","january","june","february","november","december","september","april","monday"} else lemma
    out.append({"draft_sense_id":f"staging:v21:bilingual:{rank}:{r['oewn_sense_id']}",
      "headword_id":f"core20k:rank:{rank}","rank":rank,"lemma":lemma,
      "oewn_sense_id":r["oewn_sense_id"],"definition_en_source":r["definition_en"],
      "gloss_zh_editorial":zh,"ecdict_wordlevel_reference":r["translation_zh_wordlevel_source"],
      "draft_ku_id":f"staging:v21:missing:{rank}:editorial14",
      "ku_type":"sense","render_kind":"guided_cloze",
      "question_instruction_zh":f"根据“{cue}”补全英文句子。",
      "prompt":prompt,"context_en":prompt.replace("___",response),
      "correct_answer":response,"acceptable_answers":[response],
      "source_attribution":"OEWN2025 exact Sense + ECDICT word-level evidence + original AI editorial context",
      "review_status":"AI_BILINGUAL_EDITORIAL_NEEDS_INDEPENDENT_SEMANTIC_AND_ASSESSMENT_QA",
      "independent_semantic_certified":False,"release_eligible":False,"production_ready":False})
assert len(out)>0 and len({x["draft_ku_id"] for x in out})==len(out)
dest=root/"bilingual_sense_ku_curated_batch14.jsonl"
dest.write_text("".join(json.dumps(r,ensure_ascii=False)+"\n" for r in out),encoding="utf8")
print("BILINGUAL_CURATED_BATCH14_PASS",json.dumps({"authored":len(entries),"new_bilingual_editorial_senses":len(out),"new_original_context_kus":len(out),"skipped":skipped,"independent_certified":0,"production_ready":0},ensure_ascii=False))
